  v.official_content, v.keywords, 'published', false, date '2026-09-09', timestamptz '2026-09-09 19:07:52+00'
from public.organizations o
cross join (values
($$TC-041$$, $$regla-de-24-horas$$, $$Regla de 24 horas$$, $$conducta$$, $$tannery_city$$, $$Después de un partido se solicita esperar al menos 24 horas antes de presentar inconformidades sobre minutos, titularidad, posición o decisiones tácticas/técnicas.$$, $$Después de un partido se solicita esperar al menos 24 horas antes de presentar inconformidades sobre minutos, titularidad, posición o decisiones tácticas/técnicas. No aplica a seguridad, salud, agresiones o emergencias.$$, array[$$regla$$,$$horas$$]),
($$TC-042$$, $$evaluaciones-deportivas$$, $$Evaluaciones deportivas$$, $$jugadores$$, $$tannery_city$$, $$Padres pueden solicitar evaluación. Tannery City busca realizar evaluaciones trimestrales. Información individual privada; acceso a jugador, padre/tutor, staff autorizado, Dirección y Presidencia.$$, $$Padres pueden solicitar evaluación. Tannery City busca realizar evaluaciones trimestrales. Información individual privada; acceso a jugador, padre/tutor, staff autorizado, Dirección y Presidencia.$$, array[$$evaluaciones$$,$$deportivas$$]),
($$TC-043$$, $$clima$$, $$Clima$$, $$entrenamientos$$, $$tannery_city$$, $$Ante tormenta eléctrica se suspende actividad. Con lluvia, el club procurará informar aproximadamente 40 minutos antes si continúa o se suspende.$$, $$Ante tormenta eléctrica se suspende actividad. Con lluvia, el club procurará informar aproximadamente 40 minutos antes si continúa o se suspende. Si comienza durante la sesión, entrenador puede suspender. Cancelación por clima no genera automáticamente reposición. Si la cancelación es atribuible al club, Dirección evalúa reposición.$$, array[$$clima$$]),
($$TC-044$$, $$entrenamiento-con-pocos-jugadores$$, $$Entrenamiento con pocos jugadores$$, $$entrenamientos$$, $$tannery_city$$, $$Mínimo para impartir sesión: 1 jugador. Mientras la sesión esté oficialmente programada, el club entrenará al jugador presente.$$, $$Mínimo para impartir sesión: 1 jugador. Mientras la sesión esté oficialmente programada, el club entrenará al jugador presente.$$, array[$$entrenamiento$$,$$pocos$$,$$jugadores$$]),
($$TC-045$$, $$dias-festivos$$, $$Días festivos$$, $$entrenamientos$$, $$tannery_city$$, $$El club puede consultar disponibilidad mediante encuesta. Las encuestas son consultivas; decisión final corresponde al club.$$, $$El club puede consultar disponibilidad mediante encuesta. Las encuestas son consultivas; decisión final corresponde al club.$$, array[$$días$$,$$festivos$$]),
($$TC-046$$, $$calzado$$, $$Calzado$$, $$uniformes$$, $$tannery_city$$, $$Prohibidos tachones. Permitidos multitachos / calzado deportivo autorizado.$$, $$Prohibidos tachones. Permitidos multitachos / calzado deportivo autorizado.$$, array[$$calzado$$]),
($$TC-047$$, $$espinilleras$$, $$Espinilleras$$, $$uniformes$$, $$tannery_city$$, $$No obligatorias en entrenamiento ordinario; pueden utilizarse. En competencia se sigue también el reglamento correspondiente.$$, $$No obligatorias en entrenamiento ordinario; pueden utilizarse. En competencia se sigue también el reglamento correspondiente.$$, array[$$espinilleras$$]),
($$TC-048$$, $$hidratacion$$, $$Hidratación$$, $$entrenamientos$$, $$tannery_city$$, $$Cada jugador debe llevar agua o hidratación propia.$$, $$Cada jugador debe llevar agua o hidratación propia.$$, array[$$hidratación$$]),
($$TC-049$$, $$uniformes$$, $$Uniformes$$, $$uniformes$$, $$tannery_city$$, $$Tannery City maneja 4 jerseys oficiales en rotación. Cada 6 meses se renuevan 2 de los 4 diseños y los otros 2 siguen vigentes; en el siguiente ciclo se renueva la pareja restante.$$, $$Tannery City maneja 4 jerseys oficiales en rotación. Cada 6 meses se renuevan 2 de los 4 diseños y los otros 2 siguen vigentes; en el siguiente ciclo se renueva la pareja restante. El jugador debe contar con los uniformes designados para su ciclo. Si ya tiene un modelo vigente y en buenas condiciones, no necesita duplicado.$$, array[$$uniformes$$]),
($$TC-050$$, $$short-y-medias$$, $$Short y medias$$, $$uniformes$$, $$tannery_city$$, $$Estándar Tanner: short negro y medias blancas. Podrán renovarse cuando corresponda.$$, $$Estándar Tanner: short negro y medias blancas. Podrán renovarse cuando corresponda.$$, array[$$short$$,$$medias$$]),
($$TC-051$$, $$porteros$$, $$Porteros$$, $$uniformes$$, $$tannery_city$$, $$Cada portero debe contar con mínimo 2 uniformes de distinto color para diferenciarse según uniforme del equipo y competencia.$$, $$Cada portero debe contar con mínimo 2 uniformes de distinto color para diferenciarse según uniforme del equipo y competencia.$$, array[$$porteros$$]),
($$TC-052$$, $$olvido-de-uniforme$$, $$Olvido de uniforme$$, $$uniformes$$, $$tannery_city$$, $$Puede entrenar con playera negra, short negro y medias blancas. Primera incidencia: recordatorio. Reincidencia: puede generar amonestación/formación disciplinaria.$$, $$Puede entrenar con playera negra, short negro y medias blancas. Primera incidencia: recordatorio. Reincidencia: puede generar amonestación/formación disciplinaria. En becados, incumplimiento reiterado puede influir en renovación.$$, array[$$olvido$$,$$uniforme$$]),
($$TC-053$$, $$garantia-cambios-de-uniforme$$, $$Garantía / cambios de uniforme$$, $$uniformes$$, $$tannery_city$$, $$Primeros 3 días después de entrega: reportar anomalías a Tannery City. Posteriormente y hasta aproximadamente 30 días: seguimiento conforme garantía del proveedor.$$, $$Primeros 3 días después de entrega: reportar anomalías a Tannery City. Posteriormente y hasta aproximadamente 30 días: seguimiento conforme garantía del proveedor. No aplica automáticamente a mal uso, lavado incorrecto, modificaciones o desgaste normal.$$, array[$$garantía$$,$$cambios$$,$$uniforme$$]),
($$TC-054$$, $$objetos-personales$$, $$Objetos personales$$, $$seguridad$$, $$tannery_city$$, $$Tannery City no se responsabiliza por objetos personales no entregados formalmente a resguardo, como celular, dinero, reloj, chamarra o accesorios.$$, $$Tannery City no se responsabiliza por objetos personales no entregados formalmente a resguardo, como celular, dinero, reloj, chamarra o accesorios.$$, array[$$objetos$$,$$personales$$]),
