($$TC-056$$, $$joyeria$$, $$Joyería$$, $$seguridad$$, $$tannery_city$$, $$Durante entrenamiento y partido no usar elementos que representen riesgo: cadenas, relojes, aretes o accesorios peligrosos.$$, $$Durante entrenamiento y partido no usar elementos que representen riesgo: cadenas, relojes, aretes o accesorios peligrosos.$$, array[$$joyería$$]),
($$TC-057$$, $$danos$$, $$Daños$$, $$conducta$$, $$tannery_city$$, $$Daño intencional o negligente a instalaciones, baños, mobiliario, material o propiedad del club puede ser cobrado a la persona/familia responsable.$$, $$Daño intencional o negligente a instalaciones, baños, mobiliario, material o propiedad del club puede ser cobrado a la persona/familia responsable.$$, array[$$daños$$]),
($$TC-058$$, $$material-deportivo$$, $$Material deportivo$$, $$entrenamientos$$, $$tannery_city$$, $$Fuera del entrenamiento no se presta material sin autorización. Después de sesión, quienes sigan jugando deben usar su propio balón.$$, $$Fuera del entrenamiento no se presta material sin autorización. Después de sesión, quienes sigan jugando deben usar su propio balón. Si un balón del club sale fuera debe recuperarse; cuando sea necesario, el menor lo hace acompañado por su tutor. Pérdida por incumplimiento puede generar responsabilidad de reposición.$$, array[$$material$$,$$deportivo$$]),
($$TC-059$$, $$uso-de-cancha-despues-de-entrenar$$, $$Uso de cancha después de entrenar$$, $$tannery_city_park$$, $$tannery_city$$, $$Puede permitirse permanecer jugando con disponibilidad y autorización. Referencia: hasta aproximadamente 19:00 hrs, sujeto a operación TCP.$$, $$Puede permitirse permanecer jugando con disponibilidad y autorización. Referencia: hasta aproximadamente 19:00 hrs, sujeto a operación TCP. Cuando la cancha se necesite, pueden ser canalizados a La Lechuguilla u otra zona disponible.$$, array[$$uso$$,$$cancha$$,$$después$$,$$entrenar$$]),
($$TC-060$$, $$conducta-de-jugadores$$, $$Conducta de jugadores$$, $$conducta$$, $$tannery_city$$, $$Principios: respeto, disciplina, esfuerzo, honestidad, responsabilidad y trabajo en equipo.$$, $$Principios: respeto, disciplina, esfuerzo, honestidad, responsabilidad y trabajo en equipo.$$, array[$$conducta$$,$$jugadores$$]),
